*** Begin Patch
*** Add File: output/assets/styles.css
+:root{
+  --bg:#FAFAFA;
+  --surface:#FFFFFF;
+  --text:#0B1220;
+  --muted:#586174;
+  --border:rgba(13,19,33,.12);
+  --shadow:0 14px 40px rgba(10,16,28,.08);
+  --shadow-sm:0 10px 24px rgba(10,16,28,.08);
+  --accent:#0072F5;
+  --accent-2:#FF6A00;
+  --radius:16px;
+  --radius-sm:12px;
+  --max:1180px;
+  --ring:0 0 0 4px rgba(0,114,245,.18);
+  --font: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family:var(--font);
+  color:var(--text);
+  background:linear-gradient(180deg, #FFFFFF 0%, var(--bg) 70%);
+  line-height:1.5;
+}
+
+a{color:inherit; text-decoration:none}
+button,input{font:inherit}
+
+.container{max-width:var(--max); margin:0 auto; padding:0 20px}
+
+.skip{
+  position:absolute;
+  left:-999px;
+  top:auto;
+  width:1px;
+  height:1px;
+  overflow:hidden;
+}
+.skip:focus{left:16px; top:14px; width:auto; height:auto; padding:10px 12px; border-radius:10px; background:var(--surface); box-shadow:var(--shadow-sm); z-index:999}
+
+/* Header */
+.header{
+  position:sticky;
+  top:0;
+  z-index:50;
+  border-bottom:1px solid rgba(13,19,33,.08);
+  backdrop-filter:saturate(160%) blur(10px);
+  background:rgba(250,250,250,.75);
+}
+
+.header-inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:18px;
+  padding:14px 0;
+}
+
+.brand{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  min-width:190px;
+}
+.logo{
+  width:34px;
+  height:34px;
+  border-radius:10px;
+  background:radial-gradient(80% 120% at 20% 10%, rgba(0,114,245,.9) 0%, rgba(0,114,245,.3) 48%, rgba(255,106,0,.25) 100%),
+              linear-gradient(135deg, #0B1220 0%, #1D2B4A 60%, #0B1220 100%);
+  box-shadow:0 10px 24px rgba(0,114,245,.18);
+}
+.brand-name{font-weight:800; letter-spacing:-.02em; font-size:16px}
+.brand-sub{display:block; font-size:12px; color:var(--muted); margin-top:1px}
+
+.nav{
+  display:flex;
+  align-items:center;
+  gap:18px;
+  flex:1;
+  justify-content:center;
+}
+
+.nav a, .nav button{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  padding:9px 10px;
+  border-radius:12px;
+  border:1px solid transparent;
+  color:rgba(11,18,32,.88);
+  background:transparent;
+  cursor:pointer;
+}
+.nav a:hover, .nav button:hover{background:rgba(11,18,32,.04); border-color:rgba(11,18,32,.06)}
+.nav .chev{opacity:.6; font-size:12px}
+
+.header-actions{display:flex; align-items:center; gap:10px; min-width:240px; justify-content:flex-end}
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:8px;
+  border-radius:999px;
+  border:1px solid rgba(13,19,33,.12);
+  background:var(--surface);
+  padding:9px 12px;
+  font-weight:650;
+  cursor:pointer;
+}
+.btn:hover{box-shadow:var(--shadow-sm)}
+.btn.primary{background:var(--accent); border-color:rgba(0,114,245,.3); color:white}
+.btn.primary:hover{filter:saturate(1.06) brightness(1.02)}
+.btn.ghost{background:transparent}
+.btn.small{padding:8px 10px; font-weight:650}
+
+.btn:focus-visible, .nav a:focus-visible, .nav button:focus-visible, .pill:focus-visible, .search input:focus-visible{
+  outline:none;
+  box-shadow:var(--ring);
+}
+
+/* Mega menus */
+.dropdown{position:relative}
+.menu{
+  position:absolute;
+  left:0;
+  top:46px;
+  width:min(860px, calc(100vw - 40px));
+  padding:14px;
+  border:1px solid rgba(13,19,33,.12);
+  border-radius:18px;
+  background:rgba(255,255,255,.92);
+  box-shadow:var(--shadow);
+  transform:translateY(-6px);
+  opacity:0;
+  pointer-events:none;
+  transition:opacity .16s ease, transform .16s ease;
+}
+.menu[data-open="true"]{opacity:1; transform:translateY(0); pointer-events:auto}
+.menu-grid{display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:14px}
+.menu-col{
+  padding:12px;
+  border-radius:14px;
+  background:rgba(250,250,250,.7);
+  border:1px solid rgba(13,19,33,.08);
+}
+.menu-col h4{margin:0 0 10px; font-size:12px; letter-spacing:.08em; text-transform:uppercase; color:rgba(11,18,32,.7)}
+.menu-col a{display:block; padding:8px 10px; border-radius:12px; border:1px solid transparent}
+.menu-col a:hover{background:white; border-color:rgba(0,114,245,.2)}
+.menu-col a span{display:block; font-size:12px; color:var(--muted); margin-top:2px}
+
+.menu.compact{width:min(740px, calc(100vw - 40px))}
+.menu.compact .menu-grid{grid-template-columns:repeat(3, minmax(0, 1fr))}
+
+/* Hero */
+.hero{padding:34px 0 22px}
+.hero-top{display:flex; align-items:flex-end; justify-content:space-between; gap:18px}
+.hero h1{margin:0; font-size:46px; line-height:1.05; letter-spacing:-.03em}
+.hero p{margin:12px 0 0; max-width:66ch; color:rgba(11,18,32,.78); font-size:16px}
+.hero .kicker{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  border-radius:999px;
+  padding:6px 10px;
+  background:rgba(0,114,245,.08);
+  border:1px solid rgba(0,114,245,.18);
+  color:rgba(0,114,245,.95);
+  font-weight:700;
+  letter-spacing:-.01em;
+  font-size:12px;
+  margin-bottom:14px;
+}
+
+.hero-side{
+  display:flex;
+  gap:10px;
+  align-items:center;
+  justify-content:flex-end;
+}
+
+/* Filters */
+.filters{padding:10px 0 10px}
+.filters-row{
+  display:flex;
+  align-items:center;
+  gap:12px;
+  flex-wrap:wrap;
+  justify-content:space-between;
+}
+
+.pills{display:flex; gap:10px; flex-wrap:wrap}
+.pill{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  padding:8px 12px;
+  border-radius:999px;
+  border:1px solid rgba(13,19,33,.14);
+  background:rgba(255,255,255,.8);
+  cursor:pointer;
+  font-weight:650;
+  color:rgba(11,18,32,.82);
+}
+.pill:hover{box-shadow:var(--shadow-sm)}
+.pill[data-active="true"]{
+  background:rgba(0,114,245,.12);
+  border-color:rgba(0,114,245,.32);
+  color:rgba(0,114,245,.95);
+}
+
+.search{position:relative; flex:1; min-width:240px; max-width:420px}
+.search input{
+  width:100%;
+  padding:10px 12px 10px 40px;
+  border-radius:999px;
+  border:1px solid rgba(13,19,33,.14);
+  background:rgba(255,255,255,.9);
+  outline:none;
+}
+.search .icon{
+  position:absolute;
+  left:14px;
+  top:50%;
+  transform:translateY(-50%);
+  opacity:.55;
+  font-size:14px;
+}
+
+/* Sections */
+.section-title{display:flex; align-items:baseline; justify-content:space-between; gap:14px; margin:24px 0 14px}
+.section-title h2{margin:0; font-size:18px; letter-spacing:-.02em}
+.section-title p{margin:0; font-size:13px; color:var(--muted)}
+
+/* Cards */
+.grid{display:grid; gap:14px}
+.featured-grid{grid-template-columns:1.35fr .95fr .95fr; align-items:stretch}
+.news-grid{grid-template-columns:repeat(3, minmax(0, 1fr))}
+
+.card{
+  background:rgba(255,255,255,.92);
+  border:1px solid rgba(13,19,33,.12);
+  border-radius:var(--radius);
+  padding:16px;
+  box-shadow:0 1px 0 rgba(10,16,28,.02);
+  transition:transform .14s ease, box-shadow .14s ease, border-color .14s ease;
+  display:flex;
+  flex-direction:column;
+  min-height:160px;
+}
+.card:hover{transform:translateY(-2px); box-shadow:var(--shadow-sm); border-color:rgba(0,114,245,.22)}
+
+.card .meta{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:10px}
+.tag{
+  display:inline-flex;
+  align-items:center;
+  padding:5px 10px;
+  border-radius:999px;
+  background:rgba(11,18,32,.04);
+  border:1px solid rgba(13,19,33,.10);
+  color:rgba(11,18,32,.72);
+  font-size:12px;
+  font-weight:700;
+}
+.tag.accent{background:rgba(0,114,245,.10); border-color:rgba(0,114,245,.20); color:rgba(0,114,245,.95)}
+.date{font-size:12px; color:rgba(11,18,32,.62)}
+.card h3{margin:0 0 8px; font-size:18px; letter-spacing:-.02em; line-height:1.15}
+.card p{margin:0 0 12px; color:rgba(11,18,32,.78); font-size:14px}
+
+.card .footer{
+  margin-top:auto;
+  padding-top:12px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:12px;
+  border-top:1px solid rgba(13,19,33,.08);
+}
+
+.author{display:flex; align-items:center; gap:10px; min-width:0}
+.avatar{
+  width:28px;
+  height:28px;
+  border-radius:999px;
+  background:radial-gradient(90% 120% at 30% 20%, rgba(0,114,245,.55) 0%, rgba(0,114,245,.14) 55%, rgba(255,106,0,.22) 100%),
+              linear-gradient(135deg, rgba(11,18,32,.88), rgba(29,43,74,.82));
+  border:1px solid rgba(13,19,33,.10);
+}
+.author-name{font-weight:750; font-size:13px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}
+.read{font-size:13px; font-weight:700; color:rgba(0,114,245,.92)}
+.read:hover{text-decoration:underline}
+
+.featured{
+  padding:18px;
+  border-radius:calc(var(--radius) + 2px);
+  background:
+    radial-gradient(900px 360px at 10% 0%, rgba(0,114,245,.20) 0%, rgba(0,114,245,0) 60%),
+    radial-gradient(900px 420px at 100% 10%, rgba(255,106,0,.14) 0%, rgba(255,106,0,0) 55%),
+    rgba(255,255,255,.92);
+}
+.featured h3{font-size:26px}
+.featured .meta{margin-bottom:12px}
+.featured .stats{
+  margin:12px 0 0;
+  padding:12px;
+  border-radius:14px;
+  border:1px dashed rgba(0,114,245,.25);
+  background:rgba(0,114,245,.06);
+  display:grid;
+  grid-template-columns:repeat(3, minmax(0, 1fr));
+  gap:10px;
+}
+.stat{padding:8px 10px; border-radius:12px; background:rgba(255,255,255,.7); border:1px solid rgba(13,19,33,.08)}
+.stat b{display:block; font-size:13px; letter-spacing:-.01em}
+.stat span{display:block; font-size:12px; color:rgba(11,18,32,.7); margin-top:2px}
+
+.no-results{
+  padding:18px;
+  border-radius:var(--radius);
+  border:1px solid rgba(13,19,33,.12);
+  background:rgba(255,255,255,.9);
+  color:rgba(11,18,32,.74);
+}
+
+.controls{
+  display:flex;
+  justify-content:center;
+  padding:18px 0 6px;
+}
+
+/* CTA */
+.cta{
+  margin:34px 0 26px;
+  border-radius:24px;
+  border:1px solid rgba(13,19,33,.12);
+  background:
+    radial-gradient(900px 360px at 15% 0%, rgba(0,114,245,.18) 0%, rgba(0,114,245,0) 60%),
+    radial-gradient(700px 300px at 100% 100%, rgba(255,106,0,.12) 0%, rgba(255,106,0,0) 55%),
+    rgba(255,255,255,.92);
+  box-shadow:var(--shadow-sm);
+}
+.cta-inner{display:grid; grid-template-columns:1.4fr .9fr; gap:18px; padding:22px}
+.cta h3{margin:0; font-size:20px; letter-spacing:-.02em}
+.cta p{margin:8px 0 0; color:rgba(11,18,32,.78)}
+.cta-actions{display:flex; gap:10px; flex-wrap:wrap; align-items:flex-start; justify-content:flex-end}
+.cta-side{
+  padding:16px;
+  border-radius:18px;
+  border:1px solid rgba(13,19,33,.10);
+  background:rgba(250,250,250,.65);
+}
+.cta-side h4{margin:0 0 6px; font-size:14px}
+.cta-side p{margin:0 0 10px; font-size:13px; color:rgba(11,18,32,.75)}
+
+/* Footer */
+.footer{padding:22px 0 26px; border-top:1px solid rgba(13,19,33,.10)}
+.footer-grid{display:grid; grid-template-columns:repeat(6, minmax(0, 1fr)); gap:14px}
+.footer h5{margin:0 0 10px; font-size:12px; letter-spacing:.08em; text-transform:uppercase; color:rgba(11,18,32,.70)}
+.footer a{display:block; padding:7px 0; color:rgba(11,18,32,.78)}
+.footer a:hover{color:rgba(0,114,245,.95)}
+.footer-bottom{display:flex; justify-content:space-between; gap:12px; flex-wrap:wrap; margin-top:18px; padding-top:14px; border-top:1px solid rgba(13,19,33,.08); color:rgba(11,18,32,.68); font-size:13px}
+.status{display:inline-flex; align-items:center; gap:8px; padding:6px 10px; border-radius:999px; border:1px solid rgba(13,19,33,.12); background:rgba(255,255,255,.85)}
+.dot{width:8px; height:8px; border-radius:999px; background:#18C964; box-shadow:0 0 0 4px rgba(24,201,100,.15)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .featured-grid{grid-template-columns:1fr;}
+  .featured .stats{grid-template-columns:1fr;}
+  .cta-inner{grid-template-columns:1fr;}
+  .nav{display:none}
+  .header-inner{justify-content:space-between}
+}
+
+@media (max-width: 920px){
+  .news-grid{grid-template-columns:repeat(2, minmax(0, 1fr))}
+  .footer-grid{grid-template-columns:repeat(3, minmax(0, 1fr))}
+}
+
+@media (max-width: 640px){
+  .hero h1{font-size:34px}
+  .news-grid{grid-template-columns:1fr}
+  .brand{min-width:auto}
+  .header-actions{min-width:auto}
+}
+
*** End Patch

