+    radial-gradient(700px 300px at 100% 100%, rgba(255,106,0,.12) 0%, rgba(255,106,0,0) 55%),
+    rgba(255,255,255,.92);
+  box-shadow:var(--shadow-sm);
+}
+.cta-inner{display:grid; grid-template-columns:1.4fr .9fr; gap:18px; padding:22px}
+.cta h3{margin:0; font-size:20px; letter-spacing:-.02em}
+.cta p{margin:8px 0 0; color:rgba(11,18,32,.78)}
+.cta-actions{display:flex; gap:10px; flex-wrap:wrap; align-items:flex-start; justify-content:flex-end}
+.cta-side{
+  padding:16px;
+  border-radius:18px;
+  border:1px solid rgba(13,19,33,.10);
+  background:rgba(250,250,250,.65);
+}
+.cta-side h4{margin:0 0 6px; font-size:14px}
+.cta-side p{margin:0 0 10px; font-size:13px; color:rgba(11,18,32,.75)}
+
+/* Footer */
+.footer{padding:22px 0 26px; border-top:1px solid rgba(13,19,33,.10)}
+.footer-grid{display:grid; grid-template-columns:repeat(6, minmax(0, 1fr)); gap:14px}
+.footer h5{margin:0 0 10px; font-size:12px; letter-spacing:.08em; text-transform:uppercase; color:rgba(11,18,32,.70)}
+.footer a{display:block; padding:7px 0; color:rgba(11,18,32,.78)}
+.footer a:hover{color:rgba(0,114,245,.95)}
+.footer-bottom{display:flex; justify-content:space-between; gap:12px; flex-wrap:wrap; margin-top:18px; padding-top:14px; border-top:1px solid rgba(13,19,33,.08); color:rgba(11,18,32,.68); font-size:13px}
+.status{display:inline-flex; align-items:center; gap:8px; padding:6px 10px; border-radius:999px; border:1px solid rgba(13,19,33,.12); background:rgba(255,255,255,.85)}
+.dot{width:8px; height:8px; border-radius:999px; background:#18C964; box-shadow:0 0 0 4px rgba(24,201,100,.15)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .featured-grid{grid-template-columns:1fr;}
+  .featured .stats{grid-template-columns:1fr;}
+  .cta-inner{grid-template-columns:1fr;}
+  .nav{display:none}
+  .header-inner{justify-content:space-between}
+}
+
+@media (max-width: 920px){
+  .news-grid{grid-template-columns:repeat(2, minmax(0, 1fr))}
+  .footer-grid{grid-template-columns:repeat(3, minmax(0, 1fr))}
+}
+
+@media (max-width: 640px){
+  .hero h1{font-size:34px}
+  .news-grid{grid-template-columns:1fr}
+  .brand{min-width:auto}
+  .header-actions{min-width:auto}
+}
+
*** End Patch
PATCH"}

